package com.huypc.prox
import android.app.*;import android.os.*;import android.provider.Settings;import android.graphics.Color;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import org.json.JSONObject
object C{const val API="https://huypc-prox.netlify.app"}
class MainActivity:Activity(){fun t(s:String,z:Float=14f)=TextView(this).apply{text=s;textSize=z;setTextColor(Color.WHITE)};override fun onCreate(b:Bundle?){super.onCreate(b);license()}
fun license(){val l=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(25,40,25,25);setBackgroundColor(Color.rgb(5,5,9))};val h=t("HUYPC PRO X",30f);h.gravity=17;l.addView(h);l.addView(t("🔐 LICENSE KEY"));val k=EditText(this).apply{hint="HX-XXXX-XXXX-XXXX";setTextColor(Color.WHITE);setHintTextColor(Color.GRAY);singleLine=true};l.addView(k);val s=t("SERVER: READY");l.addView(s);val b=Button(this).apply{text="ACTIVATE KEY"};l.addView(b);b.setOnClickListener{Thread{try{val id=Settings.Secure.getString(contentResolver,Settings.Secure.ANDROID_ID);val c=URL(C.API+"/api/license").openConnection() as HttpURLConnection;c.requestMethod="POST";c.doOutput=true;c.setRequestProperty("Content-Type","application/json");OutputStreamWriter(c.outputStream).use{it.write(JSONObject().put("key",k.text.toString()).put("deviceId",id).toString())};val j=JSONObject(c.inputStream.bufferedReader().readText());runOnUiThread{if(j.optBoolean("ok"))main(j.getJSONObject("license"))else s.text="KEY INVALID"}}catch(e:Exception){runOnUiThread{s.text="SERVER ERROR"}}}.start()};setContentView(l)}
fun main(x:JSONObject){val l=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(20,25,20,20);setBackgroundColor(Color.rgb(5,5,9))};l.addView(t("HUYPC PRO X",28f));l.addView(t("LICENSE ${x.optString("plan")}"));fun sp(a:Array<String>)=Spinner(this).apply{adapter=ArrayAdapter(this@MainActivity,android.R.layout.simple_spinner_dropdown_item,a)};l.addView(sp(arrayOf("Auto Device","Samsung","Xiaomi / Redmi / POCO","OPPO / Realme","Vivo")));l.addView(sp(arrayOf("60Hz","90Hz","120Hz","144Hz")));l.addView(sp(arrayOf("360 DPI","400 DPI","420 DPI","440 DPI","480 DPI")));l.addView(sp(arrayOf("ĐẦM","CÂN BẰNG","NHẸ TÂM","KÉO ĐẦU")));arrayOf("Stable Aim","Light Aim","Fast Touch","Drag Control","Vertical Control","Sensitivity Optimize","Device Optimize").forEach{l.addView(CheckBox(this).apply{text=it;isChecked=true;setTextColor(Color.WHITE)})};l.addView(Button(this).apply{text="⚡ APPLY PROFILE";setOnClickListener{Toast.makeText(this@MainActivity,"PROFILE APPLIED",0).show()}});l.addView(Button(this).apply{text="💾 SAVE PROFILE"});setContentView(ScrollView(this).apply{addView(l)})}}